/* CORDIC atan(2^-i)，i = 0..15，Q16.16 表示 */
static const int hp_atan_tbl[16] = { 51472,30386,16055,8150,4091,2047,1024,512,256,128,64,32,16,8,4,2 };

hp_fx hp_fx_int(int v)      { return (hp_fx)v << FXD; }
/* 有符号除法向零截断（对负数而言右移是取底 --
 * 对 "trunc" API 来说是错的） */
int   hp_fx_trunc(hp_fx x)  { return x / FXK; }
int   hp_fx_round(hp_fx x)  { return (x + (x < 0 ? -0x8000 : 0x8000)) / FXK; }
double hp_fx_to_double(hp_fx x) { return (double)x / FXK; }
hp_fx hp_fx_from_double(double d)
{
    return (hp_fx)(d * FXK + (d < 0.0 ? -0.5 : 0.5));
}

hp_fx hp_fx_neg(hp_fx a) { return -a; }
hp_fx hp_fx_add(hp_fx a, hp_fx b) { return a + b; }
hp_fx hp_fx_sub(hp_fx a, hp_fx b) { return a - b; }
hp_fx hp_fx_abs(hp_fx a) { return a < 0 ? -a : a; }

hp_fx hp_fx_mul(hp_fx a, hp_fx b)
{
    long long p = (long long)a * b;
    return (hp_fx)((p + 0x8000) >> FXD);
}

hp_fx hp_fx_div(hp_fx a, hp_fx b)
{
    if (b == 0)
        return 0;
    return (hp_fx)(((long long)a << FXD) / b);
}

hp_fx hp_fx_lerp(hp_fx a, hp_fx b, hp_fx t)
{
    return a + hp_fx_mul(b - a, t);
}

hp_fx hp_fx_sqrt(hp_fx x)
{
    unsigned long long v, lo, hi, mid;
    if (x <= 0)
        return 0;
    v = (unsigned long long)(unsigned)x << FXD;   /* Q32.32 = x */
    lo = 0;
    hi = (unsigned long long)FXK << 16;           /* 2^32 */
    while (lo + 1 < hi) {
        mid = (lo + hi) >> 1;
        if (mid * mid <= v)
            lo = mid;
        else
            hi = mid;
    }
    return (hp_fx)lo;                              /* Q16.16 结果 */
}

/* ---- sin/cos：象限归约 + 带插值的查表 ---- */
static hp_fx sin_core(hp_fx t)
{
    /* t 在 [0, pi/2] 内。  表下标：angle/(pi/2)*512，即 t*512/PI_2。 */
    int idx = (int)(((long long)t * 512) / HP_FX_PI_2);
    unsigned short a, b;
    int diff, frac;
    long long r;
    if (idx >= 511)
        return HP_FX_ONE - 1;
    a = hp_sin_tbl[idx];
    b = hp_sin_tbl[idx + 1];
    /* 单元格内的位置，表示为 0..65535 的分数 */
    diff = (int)((long long)t * 512 - (long long)idx * HP_FX_PI_2);
    frac = (int)(((long long)diff * 65536) / HP_FX_PI_2);
    /* 64 位中间量：a*(65536-frac) 可能超过 2^31 */
    r = (long long)a * (65536 - frac) + (long long)b * frac;
    return (hp_fx)((r + 0x8000) >> 16);
}

hp_fx hp_fx_sin(hp_fx rad)
{
    hp_fx t;
    int quad;
    /* 归约到 [0, 2pi) */
    while (rad >= HP_FX_2PI) rad -= HP_FX_2PI;
    while (rad < 0) rad += HP_FX_2PI;
    quad = (int)(rad / HP_FX_PI_2);               /* 0..3 */
    t = rad - quad * HP_FX_PI_2;                  /* [0, pi/2) */
    switch (quad) {
    case 0:  return  sin_core(t);
    case 1:  return  sin_core(HP_FX_PI_2 - t);
    case 2:  return -sin_core(t);
    default: return -sin_core(HP_FX_PI_2 - t);
    }
}

hp_fx hp_fx_cos(hp_fx rad)
{
    return hp_fx_sin(rad + HP_FX_PI_2);
}

hp_fx hp_fx_tan(hp_fx rad)
{
    return hp_fx_div(hp_fx_sin(rad), hp_fx_cos(rad));
}

/* ---- atan2：CORDIC 矢量模式，结果在 [-pi, pi] ---- */
static hp_fx cordic_atan2_core(hp_fx y, hp_fx x)
{
    /* x, y >= 0；把 (x, y) 旋转到 +x 轴上；z 累加角度 */
    hp_fx z = 0;
    int i;
    for (i = 0; i < 16; i++) {
        int d = (y >= 0) ? 1 : -1;
        int tx = x >> i;
        x += d * (y >> i);
        y -= d * tx;
        z += (d > 0) ? hp_atan_tbl[i] : -hp_atan_tbl[i];
    }
    return z;
}

hp_fx hp_fx_atan2(hp_fx y, hp_fx x)
{
    hp_fx ax, ay, ang;
    int sx, sy;
    if (x == 0 && y == 0)
        return 0;
    sx = x < 0 ? -1 : 1;
    sy = y < 0 ? -1 : 1;
    ax = hp_fx_abs(x);
    ay = hp_fx_abs(y);
    ang = cordic_atan2_core(ay, ax);              /* [0, pi/2] */
    if (sx < 0)
        ang = HP_FX_PI - ang;
    if (sy < 0)
        ang = -ang;
    return ang;
}
